set retStr = ""
set env = ..GetEnv()
set tableNm = $ZSTRIP(tableNm,"<>WC")
set crFl =  ##class(IHC.ITF.SrcCtrlPkg.SqlTableOper).%New()
Do crFl.GetSqlFileFromSvn(nmSp, tableNm, env, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), .statStr, .fileNm)
If ('##class(%File).Exists(fileNm))
{
	 return fileNm _ "does not exists"
}
set file = ##class(%File).%New(fileNm)
set stat = file.Open("R")
if ($$$ISOK(stat))
{    	
	Do file.Close()
	set stat = crFl.SqlTableOper(nmSp, fileNm, tableNm, "Import", .statStr)
	if ($$$ISOK(stat))
	{    	
		set retStr = "Completed Importing data from: " _ fileNm _ ", Details: " _ statStr

	} else
	{
		set retStr = "ERROR: Could not Import the file: " _ fileNm _" Import error: " _ statStr
	}

} else
{
	set retStr = "ERROR: Could not open file: " _ fileNm _" svn error: " _ statStr
}

return retStr

Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "ExportSqlTable: " _ tableNm)

Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup($get(%session.Data("UsNm")), $get(%session.Data("PsWd")))

set statStr = ""
set env = ..GetEnv()
set tableNm = $ZSTRIP(tableNm,"<>WC")
set crFl =  ##class(IHC.ITF.SrcCtrlPkg.SqlTableOper).%New()

set fileNm = crFl.DeployDirectory _ crFl.SqlTableDirectory _ env _"/" _ nmSp _ "-" _ tableNm _ ".txt"

set stat = crFl.SqlTableOper(nmSp, fileNm, tableNm, "Export", .statStr)

set retStr = "CreateExportFile output: " _ stat _ "; " _ statStr
if ($$$ISOK(stat))
{	
	set file = ##class(%File).%New(fileNm)
	set stat = file.Open("R")
	if ($$$ISOK(stat))
	{
		Do file.Close()
		set stat = crFl.checkInFile(nmSp, tableNm, env, cmt, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), .statStr)
		set retStr = retStr _ "; CheckIn File output: " _ stat _ "; " _ statStr
	}
	else
	{
	    set retStr = "Could not open the export file: " _ fileNm
	}
}

RETURN retStr


set retStr = ""

try {

set rStr = ""
set env = ..GetEnv()
set tableNm = $ZSTRIP(tableNm,"<>WC")
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "FindSqlFile: " _ tableNm _ ", " _ env)
set crFl =  ##class(IHC.ITF.SrcCtrlPkg.SqlTableOper).%New()
set retStr = crFl.getSvnLog(nmSp, tableNm, env, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")))
if ($L(retStr) <= 0)
{
	set retStr = "Could not find Table files for " _ tableNm
}
if ( $FIND(retStr, "Last Changed Rev") > 0)
{
	set retStr = $REPLACE(retStr, "Last Changed Rev", "<B>Last Changed Rev</B>", 0, 1, 1)
}
if ( $FIND(retStr, "Revision") > 0)
{
	set retStr = $REPLACE(retStr, "Revision", "Head Revision", 0, 1, 1)
}
} catch(err)
{
	set retStr = "Could not find Table files " _ err
}

Return retStr

set retStr = ""
set env = ..GetEnv()
set tableNm = $ZSTRIP(tableNm,"<>WC")
set crFl =  ##class(IHC.ITF.SrcCtrlPkg.SqlTableOper).%New()
Do crFl.GetSqlFileFromSvn(nmSp, tableNm, env, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), .statStr, .fileNm)
If ('##class(%File).Exists(fileNm))
{
	 return fileNm _ "does not exists"
}

set file = ##class(%File).%New(fileNm)
set stat = file.Open("R")
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "ViewDataFile: Open " _ fileNm _ ": " _ stat)
if ($$$ISOK(stat))
{    
	set retStr = "<B>Filename: </B>" _ fileNm _"<BR>"
	set firstLine = 0
	while ('file.AtEnd)
	{
		if (firstLine = 0)
		{
			set readStr = "<B>Columns:</B><BR>" _ file.ReadLine(, .sc, .stat) _"<BR><B>Data Rows:</B><BR>"
			set firstLine = 1
		}
		else
		{
			set readStr = file.ReadLine(, .sc, .stat) _"<BR>"
		}
		If $$$ISERR(sc) 
			{ set readStr = "ERROR: " _ sc  Quit }
			set retStr = retStr _ readStr
		If stat { Quit }

	}
	set retStr 	= retStr
	Do file.Close()


} else
{
	set retStr = "ERROR: Could not open file: " _ fileNm _" svn error: " _ statStr
}
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "ViewDataFile: " _ retStr)
return retStr

set sysEnv = $ZCVT($SYSTEM, "U")
